#!/bin/bash\n\n# Secrets Management Script for AgentScan with Supabase Integration\n# Manages secrets using Supabase Vault and environment variables\n\nset -euo pipefail\n\n# Script configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$(dirname \"$SCRIPT_DIR\")\")\"  # Go up two levels\nDEPLOYMENT_DIR=\"$PROJECT_ROOT/deployment\"\nENVIRONMENTS_DIR=\"$DEPLOYMENT_DIR/environments\"\n\n# Default configuration\nENVIRONMENT=\"production\"\nACTION=\"list\"\nVERBOSE=false\nDRY_RUN=false\nFORCE=false\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog_info() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nlog_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nlog_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nlog_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_verbose() {\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo -e \"${BLUE}[VERBOSE]${NC} $1\"\n    fi\n}\n\n# Function to show help\nshow_help() {\n    cat << EOF\nAgentScan Secrets Management Script\n\nUsage: $0 [OPTIONS] [ACTION] [SECRET_NAME] [SECRET_VALUE]\n\nActions:\n    list                    List all secrets for environment\n    get <name>             Get specific secret value\n    set <name> <value>     Set secret value\n    delete <name>          Delete secret\n    generate <name>        Generate random secret value\n    sync                   Sync secrets with Supabase Vault\n    export                 Export secrets to .env file\n    import <file>          Import secrets from .env file\n    rotate <name>          Rotate secret (generate new value)\n    validate               Validate all required secrets exist\n\nOptions:\n    --environment ENV      Environment (default: production)\n    --verbose             Enable verbose logging\n    --dry-run             Show what would be done without making changes\n    --force               Force action without confirmation\n    --help                Show this help message\n\nExamples:\n    $0 list --environment production\n    $0 set JWT_SECRET \"your-secret-value\"\n    $0 generate ENCRYPTION_KEY --environment staging\n    $0 sync --environment production\n    $0 export --environment development\n    $0 import .env.production --environment production\n\nEOF\n}\n\n# Function to check prerequisites\ncheck_prerequisites() {\n    local missing_tools=()\n    \n    # Check for required tools\n    if ! command -v curl &> /dev/null; then\n        missing_tools+=(\"curl\")\n    fi\n    \n    if ! command -v jq &> /dev/null; then\n        missing_tools+=(\"jq\")\n    fi\n    \n    if ! command -v openssl &> /dev/null; then\n        missing_tools+=(\"openssl\")\n    fi\n    \n    if [[ ${#missing_tools[@]} -gt 0 ]]; then\n        log_error \"Missing required tools: ${missing_tools[*]}\"\n        log_error \"Please install the missing tools and try again\"\n        return 1\n    fi\n    \n    # Check Supabase configuration\n    if [[ -z \"${SUPABASE_URL:-}\" ]] || [[ -z \"${SUPABASE_SERVICE_ROLE_KEY:-}\" ]]; then\n        log_warning \"Supabase configuration not found. Some operations may not work.\"\n        log_info \"Set SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY environment variables\"\n    fi\n    \n    return 0\n}\n\n# Function to get secret from Supabase Vault\nget_secret_from_vault() {\n    local secret_name=\"$1\"\n    \n    if [[ -z \"${SUPABASE_URL:-}\" ]] || [[ -z \"${SUPABASE_SERVICE_ROLE_KEY:-}\" ]]; then\n        log_error \"Supabase configuration required for vault operations\"\n        return 1\n    fi\n    \n    log_verbose \"Getting secret from Supabase Vault: $secret_name\"\n    \n    # Use Supabase REST API to get secret from vault\n    local vault_url=\"$SUPABASE_URL/rest/v1/vault\"\n    local response\n    \n    response=$(curl -s -X GET \\\n        -H \"apikey: $SUPABASE_SERVICE_ROLE_KEY\" \\\n        -H \"Authorization: Bearer $SUPABASE_SERVICE_ROLE_KEY\" \\\n        -H \"Content-Type: application/json\" \\\n        \"$vault_url?name=eq.$secret_name\" 2>/dev/null || echo \"\")\n    \n    if [[ -n \"$response\" ]] && echo \"$response\" | jq -e '.[0].value' >/dev/null 2>&1; then\n        echo \"$response\" | jq -r '.[0].value'\n        return 0\n    else\n        log_verbose \"Secret not found in vault: $secret_name\"\n        return 1\n    fi\n}\n\n# Function to set secret in Supabase Vault\nset_secret_in_vault() {\n    local secret_name=\"$1\"\n    local secret_value=\"$2\"\n    \n    if [[ -z \"${SUPABASE_URL:-}\" ]] || [[ -z \"${SUPABASE_SERVICE_ROLE_KEY:-}\" ]]; then\n        log_error \"Supabase configuration required for vault operations\"\n        return 1\n    fi\n    \n    log_verbose \"Setting secret in Supabase Vault: $secret_name\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would set secret in vault: $secret_name\"\n        return 0\n    fi\n    \n    # Use Supabase REST API to set secret in vault\n    local vault_url=\"$SUPABASE_URL/rest/v1/vault\"\n    local payload\n    \n    payload=$(jq -n \\\n        --arg name \"$secret_name\" \\\n        --arg value \"$secret_value\" \\\n        --arg env \"$ENVIRONMENT\" \\\n        '{\n            name: $name,\n            value: $value,\n            environment: $env,\n            created_at: now,\n            updated_at: now\n        }')\n    \n    local response\n    response=$(curl -s -X POST \\\n        -H \"apikey: $SUPABASE_SERVICE_ROLE_KEY\" \\\n        -H \"Authorization: Bearer $SUPABASE_SERVICE_ROLE_KEY\" \\\n        -H \"Content-Type: application/json\" \\\n        -H \"Prefer: return=minimal\" \\\n        -d \"$payload\" \\\n        \"$vault_url\" 2>/dev/null || echo \"\")\n    \n    if [[ $? -eq 0 ]]; then\n        log_success \"Secret set in vault: $secret_name\"\n        return 0\n    else\n        log_error \"Failed to set secret in vault: $secret_name\"\n        return 1\n    fi\n}\n\n# Function to delete secret from Supabase Vault\ndelete_secret_from_vault() {\n    local secret_name=\"$1\"\n    \n    if [[ -z \"${SUPABASE_URL:-}\" ]] || [[ -z \"${SUPABASE_SERVICE_ROLE_KEY:-}\" ]]; then\n        log_error \"Supabase configuration required for vault operations\"\n        return 1\n    fi\n    \n    log_verbose \"Deleting secret from Supabase Vault: $secret_name\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would delete secret from vault: $secret_name\"\n        return 0\n    fi\n    \n    # Use Supabase REST API to delete secret from vault\n    local vault_url=\"$SUPABASE_URL/rest/v1/vault\"\n    \n    local response\n    response=$(curl -s -X DELETE \\\n        -H \"apikey: $SUPABASE_SERVICE_ROLE_KEY\" \\\n        -H \"Authorization: Bearer $SUPABASE_SERVICE_ROLE_KEY\" \\\n        \"$vault_url?name=eq.$secret_name&environment=eq.$ENVIRONMENT\" 2>/dev/null || echo \"\")\n    \n    if [[ $? -eq 0 ]]; then\n        log_success \"Secret deleted from vault: $secret_name\"\n        return 0\n    else\n        log_error \"Failed to delete secret from vault: $secret_name\"\n        return 1\n    fi\n}\n\n# Function to generate random secret\ngenerate_secret() {\n    local secret_type=\"${1:-general}\"\n    \n    case \"$secret_type\" in\n        \"jwt\"|\"JWT_SECRET\")\n            # Generate JWT secret (base64 encoded, 32 bytes)\n            openssl rand -base64 32\n            ;;\n        \"encryption\"|\"ENCRYPTION_KEY\")\n            # Generate encryption key (hex, 32 bytes)\n            openssl rand -hex 32\n            ;;\n        \"password\")\n            # Generate password (alphanumeric, 16 chars)\n            openssl rand -base64 16 | tr -d \"=+/\" | cut -c1-16\n            ;;\n        \"api_key\")\n            # Generate API key (hex, 24 bytes)\n            openssl rand -hex 24\n            ;;\n        *)\n            # Generate general secret (base64, 24 bytes)\n            openssl rand -base64 24\n            ;;\n    esac\n}\n"# F
unction to list secrets\nlist_secrets() {\n    log_info \"Listing secrets for environment: $ENVIRONMENT\"\n    \n    # Define expected secrets for each environment\n    local required_secrets=(\n        \"DB_HOST\"\n        \"DB_NAME\"\n        \"DB_USER\"\n        \"DB_PASSWORD\"\n        \"REDIS_HOST\"\n        \"REDIS_PASSWORD\"\n        \"SUPABASE_URL\"\n        \"SUPABASE_ANON_KEY\"\n        \"SUPABASE_SERVICE_ROLE_KEY\"\n        \"JWT_SECRET\"\n        \"GITHUB_CLIENT_ID\"\n        \"GITHUB_SECRET\"\n        \"ENCRYPTION_KEY\"\n        \"SIGNING_KEY\"\n    )\n    \n    local optional_secrets=(\n        \"SMTP_HOST\"\n        \"SMTP_USER\"\n        \"SMTP_PASSWORD\"\n        \"SLACK_WEBHOOK_URL\"\n        \"WEBHOOK_URL\"\n        \"WEBHOOK_SECRET\"\n        \"PROMETHEUS_PASSWORD\"\n        \"GRAFANA_ADMIN_PASSWORD\"\n    )\n    \n    echo \"\"\n    echo \"Required Secrets:\"\n    echo \"=================\"\n    \n    for secret in \"${required_secrets[@]}\"; do\n        local status=\"❌ Missing\"\n        local source=\"\"\n        \n        # Check environment variable\n        if [[ -n \"${!secret:-}\" ]]; then\n            status=\"✅ Set (env)\"\n            source=\"environment variable\"\n        else\n            # Check Supabase Vault\n            if get_secret_from_vault \"$secret\" >/dev/null 2>&1; then\n                status=\"✅ Set (vault)\"\n                source=\"Supabase Vault\"\n            fi\n        fi\n        \n        printf \"  %-25s %s\\n\" \"$secret\" \"$status\"\n        if [[ \"$VERBOSE\" == \"true\" ]] && [[ -n \"$source\" ]]; then\n            printf \"  %-25s   Source: %s\\n\" \"\" \"$source\"\n        fi\n    done\n    \n    echo \"\"\n    echo \"Optional Secrets:\"\n    echo \"=================\"\n    \n    for secret in \"${optional_secrets[@]}\"; do\n        local status=\"⚪ Not set\"\n        local source=\"\"\n        \n        # Check environment variable\n        if [[ -n \"${!secret:-}\" ]]; then\n            status=\"✅ Set (env)\"\n            source=\"environment variable\"\n        else\n            # Check Supabase Vault\n            if get_secret_from_vault \"$secret\" >/dev/null 2>&1; then\n                status=\"✅ Set (vault)\"\n                source=\"Supabase Vault\"\n            fi\n        fi\n        \n        printf \"  %-25s %s\\n\" \"$secret\" \"$status\"\n        if [[ \"$VERBOSE\" == \"true\" ]] && [[ -n \"$source\" ]]; then\n            printf \"  %-25s   Source: %s\\n\" \"\" \"$source\"\n        fi\n    done\n    \n    echo \"\"\n}\n\n# Function to get specific secret\nget_secret() {\n    local secret_name=\"$1\"\n    \n    log_info \"Getting secret: $secret_name\"\n    \n    # First check environment variable\n    if [[ -n \"${!secret_name:-}\" ]]; then\n        log_verbose \"Found in environment variable\"\n        echo \"${!secret_name}\"\n        return 0\n    fi\n    \n    # Then check Supabase Vault\n    local vault_value\n    if vault_value=$(get_secret_from_vault \"$secret_name\"); then\n        log_verbose \"Found in Supabase Vault\"\n        echo \"$vault_value\"\n        return 0\n    fi\n    \n    log_error \"Secret not found: $secret_name\"\n    return 1\n}\n\n# Function to set secret\nset_secret() {\n    local secret_name=\"$1\"\n    local secret_value=\"$2\"\n    \n    log_info \"Setting secret: $secret_name\"\n    \n    if [[ -z \"$secret_value\" ]]; then\n        log_error \"Secret value cannot be empty\"\n        return 1\n    fi\n    \n    # Validate secret name\n    if [[ ! \"$secret_name\" =~ ^[A-Z_][A-Z0-9_]*$ ]]; then\n        log_error \"Invalid secret name format: $secret_name\"\n        log_error \"Secret names should be uppercase with underscores (e.g., JWT_SECRET)\"\n        return 1\n    fi\n    \n    # Check if secret already exists\n    if [[ \"$FORCE\" != \"true\" ]]; then\n        if [[ -n \"${!secret_name:-}\" ]] || get_secret_from_vault \"$secret_name\" >/dev/null 2>&1; then\n            log_warning \"Secret already exists: $secret_name\"\n            read -p \"Overwrite existing secret? (y/N): \" -n 1 -r\n            echo\n            if [[ ! $REPLY =~ ^[Yy]$ ]]; then\n                log_info \"Operation cancelled\"\n                return 0\n            fi\n        fi\n    fi\n    \n    # Set in Supabase Vault\n    if set_secret_in_vault \"$secret_name\" \"$secret_value\"; then\n        log_success \"Secret set successfully: $secret_name\"\n    else\n        log_error \"Failed to set secret: $secret_name\"\n        return 1\n    fi\n}\n\n# Function to delete secret\ndelete_secret() {\n    local secret_name=\"$1\"\n    \n    log_info \"Deleting secret: $secret_name\"\n    \n    # Confirm deletion\n    if [[ \"$FORCE\" != \"true\" ]]; then\n        log_warning \"This will permanently delete the secret: $secret_name\"\n        read -p \"Are you sure? (y/N): \" -n 1 -r\n        echo\n        if [[ ! $REPLY =~ ^[Yy]$ ]]; then\n            log_info \"Operation cancelled\"\n            return 0\n        fi\n    fi\n    \n    # Delete from Supabase Vault\n    if delete_secret_from_vault \"$secret_name\"; then\n        log_success \"Secret deleted successfully: $secret_name\"\n    else\n        log_error \"Failed to delete secret: $secret_name\"\n        return 1\n    fi\n}\n\n# Function to generate and set secret\ngenerate_and_set_secret() {\n    local secret_name=\"$1\"\n    \n    log_info \"Generating secret: $secret_name\"\n    \n    # Generate appropriate secret based on name\n    local secret_value\n    secret_value=$(generate_secret \"$secret_name\")\n    \n    if [[ -z \"$secret_value\" ]]; then\n        log_error \"Failed to generate secret value\"\n        return 1\n    fi\n    \n    log_verbose \"Generated secret value (length: ${#secret_value})\"\n    \n    # Set the generated secret\n    set_secret \"$secret_name\" \"$secret_value\"\n}\n\n# Function to rotate secret\nrotate_secret() {\n    local secret_name=\"$1\"\n    \n    log_info \"Rotating secret: $secret_name\"\n    \n    # Check if secret exists\n    if ! get_secret \"$secret_name\" >/dev/null 2>&1; then\n        log_error \"Secret does not exist: $secret_name\"\n        return 1\n    fi\n    \n    # Confirm rotation\n    if [[ \"$FORCE\" != \"true\" ]]; then\n        log_warning \"This will generate a new value for: $secret_name\"\n        log_warning \"Make sure to update all services that use this secret\"\n        read -p \"Continue with rotation? (y/N): \" -n 1 -r\n        echo\n        if [[ ! $REPLY =~ ^[Yy]$ ]]; then\n            log_info \"Operation cancelled\"\n            return 0\n        fi\n    fi\n    \n    # Generate and set new secret\n    generate_and_set_secret \"$secret_name\"\n}\n\n# Function to sync secrets with Supabase Vault\nsync_secrets() {\n    log_info \"Syncing secrets with Supabase Vault for environment: $ENVIRONMENT\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would sync secrets with Supabase Vault\"\n        return 0\n    fi\n    \n    # This would implement bidirectional sync between local env vars and vault\n    log_warning \"Sync functionality not yet implemented\"\n    log_info \"Use 'set' command to manually sync individual secrets\"\n}\n\n# Function to export secrets to .env file\nexport_secrets() {\n    local output_file=\"${1:-$ENVIRONMENTS_DIR/$ENVIRONMENT/.env}\"\n    \n    log_info \"Exporting secrets to: $output_file\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would export secrets to: $output_file\"\n        return 0\n    fi\n    \n    # Create directory if it doesn't exist\n    mkdir -p \"$(dirname \"$output_file\")\"\n    \n    # Create .env file with header\n    cat > \"$output_file\" << EOF\n# AgentScan Environment Variables - $ENVIRONMENT\n# Generated on $(date)\n# WARNING: This file contains sensitive information - keep secure!\n\n# Database Configuration\nDB_HOST=\"${DB_HOST:-}\"\nDB_NAME=\"${DB_NAME:-}\"\nDB_USER=\"${DB_USER:-}\"\nDB_PASSWORD=\"${DB_PASSWORD:-}\"\n\n# Redis Configuration\nREDIS_HOST=\"${REDIS_HOST:-}\"\nREDIS_PASSWORD=\"${REDIS_PASSWORD:-}\"\n\n# Supabase Configuration\nSUPABASE_URL=\"${SUPABASE_URL:-}\"\nSUPABASE_ANON_KEY=\"${SUPABASE_ANON_KEY:-}\"\nSUPABASE_SERVICE_ROLE_KEY=\"${SUPABASE_SERVICE_ROLE_KEY:-}\"\nJWT_SECRET=\"${JWT_SECRET:-}\"\n\n# GitHub OAuth Configuration\nGITHUB_CLIENT_ID=\"${GITHUB_CLIENT_ID:-}\"\nGITHUB_SECRET=\"${GITHUB_SECRET:-}\"\n\n# Security Keys\nENCRYPTION_KEY=\"${ENCRYPTION_KEY:-}\"\nSIGNING_KEY=\"${SIGNING_KEY:-}\"\n\n# SMTP Configuration\nSMTP_HOST=\"${SMTP_HOST:-}\"\nSMTP_USER=\"${SMTP_USER:-}\"\nSMTP_PASSWORD=\"${SMTP_PASSWORD:-}\"\n\n# Notification Configuration\nSLACK_WEBHOOK_URL=\"${SLACK_WEBHOOK_URL:-}\"\nWEBHOOK_URL=\"${WEBHOOK_URL:-}\"\nWEBHOOK_SECRET=\"${WEBHOOK_SECRET:-}\"\n\n# Monitoring Configuration\nPROMETHEUS_PASSWORD=\"${PROMETHEUS_PASSWORD:-}\"\nGRAFANA_ADMIN_PASSWORD=\"${GRAFANA_ADMIN_PASSWORD:-}\"\nEOF\n    \n    # Set secure permissions\n    chmod 600 \"$output_file\"\n    \n    log_success \"Secrets exported to: $output_file\"\n    log_warning \"File contains sensitive information - keep secure!\"\n}\n\n# Function to import secrets from .env file\nimport_secrets() {\n    local input_file=\"$1\"\n    \n    if [[ ! -f \"$input_file\" ]]; then\n        log_error \"Input file not found: $input_file\"\n        return 1\n    fi\n    \n    log_info \"Importing secrets from: $input_file\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would import secrets from: $input_file\"\n        return 0\n    fi\n    \n    # Read and process .env file\n    local imported_count=0\n    local failed_count=0\n    \n    while IFS= read -r line; do\n        # Skip comments and empty lines\n        if [[ \"$line\" =~ ^#.*$ ]] || [[ -z \"$line\" ]]; then\n            continue\n        fi\n        \n        # Parse KEY=VALUE format\n        if [[ \"$line\" =~ ^([A-Z_][A-Z0-9_]*)=(.*)$ ]]; then\n            local key=\"${BASH_REMATCH[1]}\"\n            local value=\"${BASH_REMATCH[2]}\"\n            \n            # Remove quotes if present\n            value=$(echo \"$value\" | sed 's/^\"\\(.*\\)\"$/\\1/' | sed \"s/^'\\(.*\\)'$/\\1/\")\n            \n            # Skip empty values\n            if [[ -z \"$value\" ]]; then\n                log_verbose \"Skipping empty value for: $key\"\n                continue\n            fi\n            \n            log_verbose \"Importing: $key\"\n            \n            if set_secret \"$key\" \"$value\"; then\n                ((imported_count++))\n            else\n                ((failed_count++))\n            fi\n        fi\n    done < \"$input_file\"\n    \n    log_success \"Import completed: $imported_count imported, $failed_count failed\"\n}\n\n# Function to validate all required secrets\nvalidate_secrets() {\n    log_info \"Validating required secrets for environment: $ENVIRONMENT\"\n    \n    local required_secrets=(\n        \"DB_HOST\"\n        \"DB_NAME\"\n        \"DB_USER\"\n        \"DB_PASSWORD\"\n        \"SUPABASE_URL\"\n        \"SUPABASE_ANON_KEY\"\n        \"JWT_SECRET\"\n    )\n    \n    local missing_secrets=()\n    \n    for secret in \"${required_secrets[@]}\"; do\n        if ! get_secret \"$secret\" >/dev/null 2>&1; then\n            missing_secrets+=(\"$secret\")\n        else\n            log_verbose \"Found required secret: $secret\"\n        fi\n    done\n    \n    if [[ ${#missing_secrets[@]} -gt 0 ]]; then\n        log_error \"Missing required secrets:\"\n        printf '  %s\\n' \"${missing_secrets[@]}\"\n        log_info \"Use 'generate' or 'set' commands to create missing secrets\"\n        return 1\n    fi\n    \n    log_success \"All required secrets are available\"\n    return 0\n}\n\n# Main function\nmain() {\n    # Check prerequisites\n    if ! check_prerequisites; then\n        exit 1\n    fi\n    \n    # Load environment-specific variables if .env file exists\n    local env_file=\"$ENVIRONMENTS_DIR/$ENVIRONMENT/.env\"\n    if [[ -f \"$env_file\" ]]; then\n        log_verbose \"Loading environment variables from: $env_file\"\n        set -a\n        source \"$env_file\"\n        set +a\n    fi\n    \n    # Execute action\n    case \"$ACTION\" in\n        \"list\")\n            list_secrets\n            ;;\n        \"get\")\n            if [[ -z \"${SECRET_NAME:-}\" ]]; then\n                log_error \"Secret name required for get action\"\n                exit 1\n            fi\n            get_secret \"$SECRET_NAME\"\n            ;;\n        \"set\")\n            if [[ -z \"${SECRET_NAME:-}\" ]] || [[ -z \"${SECRET_VALUE:-}\" ]]; then\n                log_error \"Secret name and value required for set action\"\n                exit 1\n            fi\n            set_secret \"$SECRET_NAME\" \"$SECRET_VALUE\"\n            ;;\n        \"delete\")\n            if [[ -z \"${SECRET_NAME:-}\" ]]; then\n                log_error \"Secret name required for delete action\"\n                exit 1\n            fi\n            delete_secret \"$SECRET_NAME\"\n            ;;\n        \"generate\")\n            if [[ -z \"${SECRET_NAME:-}\" ]]; then\n                log_error \"Secret name required for generate action\"\n                exit 1\n            fi\n            generate_and_set_secret \"$SECRET_NAME\"\n            ;;\n        \"rotate\")\n            if [[ -z \"${SECRET_NAME:-}\" ]]; then\n                log_error \"Secret name required for rotate action\"\n                exit 1\n            fi\n            rotate_secret \"$SECRET_NAME\"\n            ;;\n        \"sync\")\n            sync_secrets\n            ;;\n        \"export\")\n            export_secrets \"${SECRET_FILE:-}\"\n            ;;\n        \"import\")\n            if [[ -z \"${SECRET_FILE:-}\" ]]; then\n                log_error \"File path required for import action\"\n                exit 1\n            fi\n            import_secrets \"$SECRET_FILE\"\n            ;;\n        \"validate\")\n            validate_secrets\n            ;;\n        *)\n            log_error \"Unknown action: $ACTION\"\n            show_help\n            exit 1\n            ;;\n    esac\n}\n\n# Parse command line arguments\nSECRET_NAME=\"\"\nSECRET_VALUE=\"\"\nSECRET_FILE=\"\"\n\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        list|get|set|delete|generate|rotate|sync|export|import|validate)\n            ACTION=\"$1\"\n            shift\n            ;;\n        --environment)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --verbose)\n            VERBOSE=true\n            shift\n            ;;\n        --dry-run)\n            DRY_RUN=true\n            shift\n            ;;\n        --force)\n            FORCE=true\n            shift\n            ;;\n        --help|-h)\n            show_help\n            exit 0\n            ;;\n        *)\n            # Handle positional arguments based on action\n            if [[ \"$ACTION\" == \"get\" ]] || [[ \"$ACTION\" == \"delete\" ]] || [[ \"$ACTION\" == \"generate\" ]] || [[ \"$ACTION\" == \"rotate\" ]]; then\n                if [[ -z \"$SECRET_NAME\" ]]; then\n                    SECRET_NAME=\"$1\"\n                else\n                    log_error \"Unexpected argument: $1\"\n                    exit 1\n                fi\n            elif [[ \"$ACTION\" == \"set\" ]]; then\n                if [[ -z \"$SECRET_NAME\" ]]; then\n                    SECRET_NAME=\"$1\"\n                elif [[ -z \"$SECRET_VALUE\" ]]; then\n                    SECRET_VALUE=\"$1\"\n                else\n                    log_error \"Unexpected argument: $1\"\n                    exit 1\n                fi\n            elif [[ \"$ACTION\" == \"import\" ]] || [[ \"$ACTION\" == \"export\" ]]; then\n                if [[ -z \"$SECRET_FILE\" ]]; then\n                    SECRET_FILE=\"$1\"\n                else\n                    log_error \"Unexpected argument: $1\"\n                    exit 1\n                fi\n            else\n                log_error \"Unknown option: $1\"\n                show_help\n                exit 1\n            fi\n            shift\n            ;;\n    esac\ndone\n\n# Make script executable\nchmod +x \"$0\"\n\n# Run main function\nmain\n"